def resolve_batch(q):
    """Protocol, receipts, and accepted representatives for one batch.

    count, summary, and accepted share this path so their counts agree.
    Identity and acceptance follow vendor/protocol-1.md and
    vendor/protocol-2.md. Returns None for an unsupported protocol.
    """
    protocol = q.get("protocol", CURRENT_PROTOCOL)
    if protocol not in SUPPORTED_PROTOCOLS:
        return None
    receipts = q.get("receipts", [])
    return protocol, receipts, accepted_receipts(receipts, protocol)

def batch_summary(q):
    """Counts for a receipt batch, shared by count and summary.

    summary takes a batch from any number of accounts; count keeps its
    original single-account use.
    """
    resolved = resolve_batch(q)
    if resolved is None:
        return {"error": "unsupported_protocol"}
    protocol, receipts, accepted = resolved
    return {
        "protocol": protocol,
        "accepted_count": len(accepted),
        "duplicate_count": len(receipts) - len(accepted),
    }

def batch_accepted(q):
    """Counts plus the accepted representatives, unchanged and in input order."""
    resolved = resolve_batch(q)
    if resolved is None:
        return {"error": "unsupported_protocol"}
    protocol, receipts, accepted = resolved
    return {
        "protocol": protocol,
        "accepted_count": len(accepted),
        "duplicate_count": len(receipts) - len(accepted),
        "receipts": accepted,
    }

if command == "accepted":
    return batch_accepted(q)
if command in ("count", "summary"):
    return batch_summary(q)
